\[\begin{align*}
B_z &= \int dB_z = \frac{\mu_0 m}{4\pi\delta}\int_0^{\infty}dz\,\frac{1}{r'^3}\left(2 - \frac{3r^2\sin^2\theta}{r'^2}\right) \\
&= \frac{\mu_0 m}{4\pi\delta r^2\sin^2\theta}\int_{-\cot\theta}^{\infty}du\left[2(u^2+1)^{-3/2} - 3(u^2+1)^{-5/2}\right] \\
&= \frac{\mu_0 m}{4\pi\delta r^2\sin^2\theta}\left[\frac{2u}{\sqrt{u^2+1}} - \frac{2u^3+3u}{(u^2+1)^{3/2}}\right]_{-\cot\theta}^{\infty} \\
&= -\frac{\mu_0 m\cos\theta}{4\pi\delta r^2}
\end{align*}\]
